__global__ void batch_lower_copy_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int n,
    int batch
) {
    const int total_rows = batch * n;
    for (int linear_row = static_cast<int>(blockIdx.x);
         linear_row < total_rows;
         linear_row += static_cast<int>(gridDim.x)) {
        const int row = linear_row % n;
        const long long base = static_cast<long long>(linear_row) * n;
        const int full_vectors = (row + 1) / 4;
        const float4* input_vectors = reinterpret_cast<const float4*>(
            input + base
        );
        float4* output_vectors = reinterpret_cast<float4*>(output + base);
        for (int vector = threadIdx.x; vector < full_vectors;
             vector += blockDim.x) {
            output_vectors[vector] = input_vectors[vector];
        }
        const int tail = full_vectors * 4;
        for (int col = tail + threadIdx.x; col <= row; col += blockDim.x) {
            output[base + col] = input[base + col];
        }
    }
}

void batch_lower_copy_cuda(torch::Tensor input, torch::Tensor output) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(
        input.scalar_type() == torch::kFloat32
        && output.scalar_type() == torch::kFloat32,
        "FP32 tensors required"
    );
    TORCH_CHECK(
        input.dim() == 3 && input.size(1) == input.size(2)
        && input.is_contiguous() && output.is_contiguous()
        && input.sizes() == output.sizes(),
        "matching contiguous batched square matrices required"
    );
